import Foundation

/// Material and shape names in every language the Open Food Facts taxonomy records.
///
/// Contributed data is not in English. A sample of one real category came back with 7%
/// of its packaging identifiers carrying another language's prefix — `es:Plástico`,
/// `fr:Papier métallisé`, `es:Bandeja`, `de:wickler` — and every one of them used to
/// land in the residual bin, because a term the taxonomy cannot match is stored exactly
/// as the contributor typed it.
///
/// None of these mappings is written by hand. They are the taxonomy's own translations,
/// generated by Tools/generate-taxonomy.py, which drops any term that names two
/// different materials rather than picking one.
///
/// Loaded from a bundled resource rather than compiled in: there are over three thousand
/// of them, and a Swift dictionary literal that size does not type check in any useful
/// amount of time.
struct OFFSynonyms: Sendable {
    static let shared = OFFSynonyms()

    private let materials: [String: TaxonomyID]
    private let shapes: [String: TaxonomyID]
    /// The same terms without their language, for when a contributor labels the language
    /// wrongly — which happens often enough to be worth one last attempt. Terms that are
    /// ambiguous once the language is dropped are left out.
    private let materialsAnyLanguage: [String: TaxonomyID]
    private let shapesAnyLanguage: [String: TaxonomyID]

    init() {
        let payload = Self.load()
        materials = payload.materials
        shapes = payload.shapes
        materialsAnyLanguage = Self.stripLanguages(from: payload.materials)
        shapesAnyLanguage = Self.stripLanguages(from: payload.shapes)
    }

    func material(for id: TaxonomyID) -> TaxonomyID? { materials[id.value] }
    func shape(for id: TaxonomyID) -> TaxonomyID? { shapes[id.value] }
    func materialInAnyLanguage(for term: String) -> TaxonomyID? { materialsAnyLanguage[term] }
    func shapeInAnyLanguage(for term: String) -> TaxonomyID? { shapesAnyLanguage[term] }

    var materialCount: Int { materials.count }
    var shapeCount: Int { shapes.count }

    // MARK: - Loading

    private struct Payload: Decodable {
        var materials: [String: TaxonomyID]
        var shapes: [String: TaxonomyID]
    }

    private static func load() -> Payload {
        let empty = Payload(materials: [:], shapes: [:])
        guard let url = candidateURLs.first(where: { FileManager.default.fileExists(atPath: $0.path) }),
              let data = try? Data(contentsOf: url),
              let payload = try? JSONDecoder().decode(Payload.self, from: data) else {
            // A missing synonym table costs non-English terms, not correctness: every
            // English identifier still resolves. ./Tools/verify-bundle.sh fails if the
            // resource is absent, so this path should never be taken in a shipped build.
            return empty
        }
        return payload
    }

    /// Xcode flattens resource folders in some configurations and keeps them in others,
    /// so both are searched — the same thing that once silently emptied the rule
    /// library.
    private static var candidateURLs: [URL] {
        var urls: [URL] = []

        // The host test harnesses compile these files straight with swiftc and have no
        // bundle at all, so they point at the resource directly — the same convention
        // BINMATE_RULES already uses for the city rulesets.
        if let override = ProcessInfo.processInfo.environment["BINMATE_SYNONYMS"] {
            urls.append(URL(fileURLWithPath: override))
        }

        let bundles = [Bundle.main] + Bundle.allBundles
        for bundle in bundles {
            if let url = bundle.url(forResource: "off-synonyms", withExtension: "json") {
                urls.append(url)
            }
            if let url = bundle.url(
                forResource: "off-synonyms",
                withExtension: "json",
                subdirectory: "Resources"
            ) {
                urls.append(url)
            }
        }
        return urls
    }

    /// Drops the language prefix, keeping only terms that stay unambiguous without it.
    private static func stripLanguages(from table: [String: TaxonomyID]) -> [String: TaxonomyID] {
        var result: [String: TaxonomyID] = [:]
        var ambiguous: Set<String> = []

        for (handle, id) in table {
            let term = handle.contains(":")
                ? String(handle[handle.index(after: handle.firstIndex(of: ":")!)...])
                : handle
            if let existing = result[term], existing != id {
                ambiguous.insert(term)
            } else {
                result[term] = id
            }
        }
        for term in ambiguous { result.removeValue(forKey: term) }
        return result
    }
}
